import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Ensure proper datetime dtypes for comparisons/arithmetic.
    if not target.empty:
        target["status_ts"] = pd.to_datetime(target["status_ts"])
    if not events.empty:
        events["event_ts"] = pd.to_datetime(events["event_ts"])

    high_ts = watermark["high_ts"].iloc[0]
    high_ts = pd.to_datetime(high_ts)

    # 1. Keep only events strictly after the watermark.
    if not events.empty:
        events = events[events["event_ts"] > high_ts]

    # Deterministic sequential application order: (event_ts, event_seq).
    events = events.sort_values(
        ["event_ts", "event_seq"], kind="mergesort"
    ).reset_index(drop=True)

    seven_days = pd.Timedelta(days=7)

    # Build initial state from target_snapshot.
    state = {}
    for _, row in target.iterrows():
        state[row["user_id"]] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"],
        }

    # Apply events sequentially, in global (event_ts, event_seq) order.
    for _, ev in events.iterrows():
        uid = ev["user_id"]
        op = ev["op"]
        ts = ev["event_ts"]
        email = ev["email"]

        cur = state.get(uid)

        if op == "D":
            # Soft delete: status becomes DELETED, status_ts updated,
            # email PRESERVED as of deletion (existing email if any).
            if cur is None:
                # No prior record: nothing to preserve, use event's email.
                state[uid] = {
                    "email": email,
                    "status": "DELETED",
                    "status_ts": ts,
                }
            else:
                state[uid] = {
                    "email": cur["email"],
                    "status": "DELETED",
                    "status_ts": ts,
                }
        elif op == "U":
            if cur is None or cur["status"] == "ACTIVE":
                # New user or update on an ACTIVE user: normal upsert.
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            else:
                # cur['status'] == 'DELETED'
                # Resurrection only if strictly more than 7 days after
                # the deletion's status_ts; otherwise discard the update.
                if ts > (cur["status_ts"] + seven_days):
                    state[uid] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                else:
                    # Sticky deletion window: discard the update.
                    pass
        # Unknown op values are ignored (not part of legacy semantics).

    rows = []
    for uid, s in state.items():
        rows.append(
            {
                "user_id": uid,
                "email": s["email"],
                "status": s["status"],
                "status_ts": s["status_ts"],
            }
        )

    new_snapshot = pd.DataFrame(
        rows, columns=["user_id", "email", "status", "status_ts"]
    )

    if not new_snapshot.empty:
        new_snapshot = new_snapshot.sort_values(
            "user_id", kind="mergesort"
        ).reset_index(drop=True)

    return {"new_snapshot": new_snapshot}
